    pub fn is_codegen_valid_for(metadata: &::subxt_core::Metadata) -> bool {
        let runtime_metadata_hash = metadata
            .hasher()
            .only_these_pallets(&PALLETS)
            .only_these_runtime_apis(&RUNTIME_APIS)
            .hash();
        runtime_metadata_hash
            == [
                70u8, 121u8, 230u8, 222u8, 112u8, 166u8, 72u8, 128u8, 63u8, 87u8, 76u8, 4u8, 33u8,
                238u8, 137u8, 15u8, 238u8, 4u8, 113u8, 35u8, 226u8, 85u8, 242u8, 249u8, 35u8, 16u8,
                3u8, 110u8, 109u8, 138u8, 221u8, 160u8,
            ]
    }
